{
  "name": "@telemetry-dev/opencode",
  "version": "0.2.7",
  "description": "opencode coding-agent telemetry integration for telemetry.dev.",
  "keywords": [
    "agents",
    "coding-agent",
    "genai",
    "llm",
    "observability",
    "opencode",
    "opentelemetry",
    "telemetry",
    "tracing"
  ],
  "homepage": "https://telemetry.dev",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/telemetry-dev/telemetry.git",
    "directory": "packages/opencode"
  },
  "files": [
    "dist",
    "src"
  ],
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.mts",
      "import": "./dist/index.mjs",
      "default": "./dist/index.mjs"
    },
    "./server": {
      "types": "./dist/server.d.mts",
      "import": "./dist/server.mjs",
      "default": "./dist/server.mjs"
    },
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opentelemetry/api": "^1.9.1",
    "@telemetry-dev/sdk": "^0.2.7"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.9",
    "@opencode-ai/sdk": "1.18.9",
    "@opentelemetry/sdk-logs": "^0.223.0",
    "@opentelemetry/sdk-trace-base": "^2.12.0",
    "@types/node": "^25.5.0",
    "@typescript/native-preview": "7.0.0-dev.20260328.1",
    "typescript": "^6.0.2",
    "vite-plus": "0.1.20",
    "vitest": "npm:@voidzero-dev/vite-plus-test@0.1.20"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.11"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "engines": {
    "opencode": ">=1.15.11"
  },
  "scripts": {
    "build": "pnpm exec vp pack",
    "dev": "pnpm exec vp pack --watch",
    "test": "vp test",
    "check": "vp check"
  }
}
